    const used_quantity = ref('')
    const produced_quantity = ref('')
    const waste_quantity = ref('')
    const orderItems = ref([])
    const producedItems = ref([])
    const pushProductItem = ()=>{
      producedItems.value.push({
        Sno :  productItems.value.length + 1,
        item : productItem.value.name,
        item_id : productItem.value.id,
        unit : unit.value.name,
        unit_id : unit.value.id,
        quantity : produced_quantity.value
      }
      )
    }

    const usedItems = ref([])
    const usedItem = ref('')
        const pushUsedItem = ()=>{
      usedItems.value.push({
        Sno :  usedItems.value.length + 1,
        item : usedItem.value.name,
        item_id : usedItem.value.id,
        unit : unit.value.name,
        unit_id : unit.value.id,
        quantity : used_quantity.value
      }
      )
    }

       const wastes = ref([])
        const pushWaste = ()=>{
     wastes.value.push({
        Sno :  wastes.value.length + 1,
        item : item.value,
        unit : unit.value.name,
        unit_id : unit.value.id,
        quantity : waste_quantity.value
      }
      )
    }

     const pullItem = (sno) => {
        orderItems.value = orderItems.value.filter(item => item.Sno !== sno);
        orderItems.value = orderItems.value.map((item, index) => ({
            ...item,
            Sno: index + 1
        }));
    };

    const rawItems = ref([])


         const pullWaste = (sno) => {
        wastes.value = wastes.value.filter(item => item.Sno !== sno);
        wastes.value = wastes.value.map((item, index) => ({
            ...item,
            Sno: index + 1
        }));
    };

             const pullUsedItem = (sno) => {
        usedItems.value = usedItems.value.filter(item => item.Sno !== sno);
        usedItems.value =  usedItems.value.map((item, index) => ({
            ...item,
            Sno: index + 1
        }));
    };


    const editingRow = ref({});
    const name = ref('');
    const short_name = ref('');
    const status = ref('');
    const loading_spinner = ref(false);
    const columns = ref(['SNo','project', 'description', 'date', 'issuer', 'actions']);
    const work_orders = ref([]);
    const work_order_registration = ref(false);
    const table_option = ref({
        perPage: 10,
        perPageValues: [10, 20, 50],
        skin: 'table table-hover table-striped',
        columnsClasses: { actions: 'actions text-center' },
        sortable: ['SNo', 'name','short_name','status'],
        sortIcon: {
            base: 'sort-icon-none',
            up: 'sort-icon-asc',
            down: 'sort-icon-desc',
        },
        pagination: { nav: 'scroll', chunk: 5 },
        texts: {
            count: 'Showing {from} to {to} of {count}',
            filter: '',
            filterPlaceholder: 'Search...',
            limit: 'Results:',
        },
        resizableColumns: false,
    });

    const getWorkOrders = () => {
        loading_spinner.value = true;
        axiosInstance.get('/work-orders').then((response) => {
            
            work_orders.value = response.data.map((item, index) => {
                
                return {
                    ...item,
                    SNo: index + 1,
                    date: formatDate(item.date)
                };
            });
            
            loading_spinner.value = false;
        }).catch(error => {
            showError(error.message || "Failed to fetch work_orders");
            loading_spinner.value = false;
        });
    };


    const showMessage = inject('showMessage');
    const showError = inject('showError');






    const resetForm = () => {
    name.value = '';
    short_name.value = '';
    status.value = '';
};

const project = ref('')

const units = ref([])
const unit = ref('')
const getUnits = async()=>{
  const response = await axiosInstance.get('units')
  units.value = response.data
}


const order_group_id = ref(746)
const workOrderItem = ref('')
const workOrderItems = ref([])
const getWorkOrderItems = async()=>{
  const response = await axiosInstance.get(`work-order-items?order_group_id=${order_group_id.value}`)
  workOrderItems.value = response.data
}

const productItems = ref([])
const productItem = ref('')
const getProductItems = async()=>{
  const response = await axiosInstance.get('items-produced')
  productItems.value = response.data
}

const description = ref('')
const submitFabrication = async()=>{
    const payload = {
      entry_id : 761,
      item_used : usedItems.value,
      item_produced : producedItems.value,
      waste_produced  : wastes.value
    }


    try{
      const response = await axiosInstance.post('store-fabrication',payload)
      showMessage('Fabrication Created!')
    }catch(error){
        console.log(error)
        showError(error.message)
    }
}



const props = defineProps({
